import json
import time

# Biến đầu vào có sẵn: PARTY, HHMM, DATE_ISO, DATE_DMY, NAME, PHONE, EMAIL
URL = "https://lauphan.com/dat-ban?type=lauphan"
COSO_VALUE = "5b86181d441ef51234e765da"  # Lẩu Phan Hoàng Quốc Việt (như bản cũ)


def js_str(x):
    return json.dumps(x, ensure_ascii=False)


def wait_until(pred, what, timeout=15.0, step=0.2):
    """Vòng lặp ngắn: kiểm tra mỗi 0.2s, tối đa 15s."""
    end = time.time() + timeout
    while True:
        try:
            r = pred()
        except Exception:
            r = None
        if r:
            return r
        if time.time() >= end:
            raise RuntimeError("Timeout chờ: " + what)
        time.sleep(step)


def exists(eid):
    return bool(js(f"return !!document.getElementById({js_str(eid)})"))


def get_options(sid):
    return js(
        f"""(()=>{{
            const s=document.getElementById({js_str(sid)});
            if(!s) return [];
            return [...s.options].map(o=>({{v:o.value,t:o.text}}));
        }})()"""
    ) or []


def set_select(sid, matcher, label):
    """Tìm option theo nội dung/giá trị, gán value, dispatch input + change."""
    def find():
        if not exists(sid):
            return None
        cands = [o for o in get_options(sid) if matcher(o["v"], o["t"])]
        return cands or None

    cands = wait_until(find, f"option cho {label} trong #{sid}")
    value = cands[0]["v"]
    js(
        f"""(()=>{{
            const s=document.getElementById({js_str(sid)});
            s.value={js_str(value)};
            s.dispatchEvent(new Event('input',{{bubbles:true}}));
            s.dispatchEvent(new Event('change',{{bubbles:true}}));
            return s.value;
        }})()"""
    )
    return value


def fill_input(iid, val):
    """Điền ô text. Bỏ qua nếu ô không tồn tại trên trang."""
    if not exists(iid):
        print(f"Bỏ qua: không có ô #{iid}")
        return False
    js(
        f"""(()=>{{
            const el=document.getElementById({js_str(iid)});
            el.focus();
            el.select && el.select();
            return true;
        }})()"""
    )
    type_text(str(val))
    time.sleep(0.2)
    return True


# ---------- 1. Mở trang ----------
goto_url(URL)
wait_for_load()
wait_until(lambda: exists("selectCoso") and exists("selectSoNguoi"), "form đặt bàn")

# ---------- 2. Chọn chi nhánh ----------
coso = set_select("selectCoso", lambda v, t: v == COSO_VALUE, "chi nhánh")
print("Chi nhánh:", coso)

# ---------- 3. Số người ----------
party = set_select(
    "selectSoNguoi",
    lambda v, t: v == str(PARTY) or t.strip() == str(PARTY),
    "số người",
)
print("Số người:", party)

# ---------- 4. Ngày (select ghi "Ngày mai") ----------
day = set_select(
    "selectDay",
    lambda v, t: t.strip() == "Ngày mai" or v == "1",
    "ngày mai",
)
print("Ngày:", day)

# ---------- 5. Chờ danh sách giờ tải xong rồi chọn giờ ----------
def hour_match(v, t):
    return v.startswith(HHMM) or t.strip().startswith(HHMM)


wait_until(
    lambda: any(hour_match(o["v"], o["t"]) for o in get_options("selectHour")),
    f"danh sách giờ chứa {HHMM}",
)
hour = set_select("selectHour", hour_match, f"giờ {HHMM}")
print("Giờ:", hour)

# ---------- 6. Điền thông tin ----------
fill_input("nameOrder", NAME)
fill_input("sdtOrder", PHONE)
if EMAIL:
    fill_input("email", EMAIL)  # trên trang hiện tại không có ô email → tự bỏ qua

time.sleep(0.5)

# ---------- 7. Kiểm tra giá trị các ô ----------
vals = js(
    """(()=>{
        const g=id=>{const e=document.getElementById(id);return e?e.value:null;};
        const h=document.getElementById('selectHour');
        return {
            coso: g('selectCoso'),
            party: g('selectSoNguoi'),
            day: g('selectDay'),
            hour: g('selectHour'),
            hourText: h && h.selectedIndex>=0 ? h.options[h.selectedIndex].text : null,
            name: g('nameOrder'),
            phone: g('sdtOrder')
        };
    })()"""
)

errors = []
if vals["coso"] != COSO_VALUE:
    errors.append(f"chi nhánh={vals['coso']!r}")
if str(vals["party"]) != str(PARTY):
    errors.append(f"số người={vals['party']!r} (cần {PARTY})")
if vals["day"] != day:
    errors.append(f"ngày={vals['day']!r} (cần {day!r})")
if not (vals["hour"] and hour_match(vals["hour"], vals["hourText"] or "")):
    errors.append(f"giờ={vals['hour']!r}/{vals['hourText']!r} (cần {HHMM})")
if vals["name"] != NAME:
    errors.append(f"tên={vals['name']!r}")
if vals["phone"] != PHONE:
    errors.append(f"SĐT={vals['phone']!r}")

print("Giá trị hiện tại:", vals)
if errors:
    raise ValueError("Giá trị ô không đúng: " + "; ".join(errors))

print("OK: đã điền đúng các ô (chưa gửi form).")
